pub const DirectDependencies = struct {
    owners: std.array_list.Managed(DirectOwner),
    rows: std.array_list.Managed(DirectRow),

pub fn init(allocator: Allocator) DirectDependencies {
            return DirectDependencies{ .owners = std.array_list.Managed(DirectOwner).init(allocator), .rows = std.array_list.Managed(DirectRow).init(allocator) };
    }

pub fn deinit(self: *DirectDependencies) void {
            _ = self.owners.deinit();
            _ = self.rows.deinit();
    }

pub fn snapshot(allocator: Allocator, lockfile: *const Lockfile) DirectDependencies {
            const pkg_res: []const Resolution = lockfile.packages.items(.resolution);
            const dep_slices: []const Lockfile.DependencySlice = lockfile.packages.items(.dependencies);
            const res_slices = lockfile.packages.items(.resolutions);
            const deps = lockfile.buffers.dependencies.items;
            const resolutions = lockfile.buffers.resolutions.items;
            var out = DirectDependencies.init(allocator);
            _ = &out;
            {
                var owner: i32 = 0;
                _ = &owner;
                const __end_0 = pkg_res.len;
                while (owner < __end_0) : (owner += 1) {
                    if (((pkg_res[@as(usize, @intCast(owner))].tag != .root) and (pkg_res[@as(usize, @intCast(owner))].tag != .workspace))) {
                        continue;
                    }
                    const start: u32 = @intCast(out.rows.items.len);
                    const owner_deps = dep_slices[@as(usize, @intCast(owner))].get(deps);
                    const owner_res = res_slices[@as(usize, @intCast(owner))].get(resolutions);
                    {
                        var i: i32 = 0;
                        _ = &i;
                        const __end_1 = owner_deps.len;
                        while (i < __end_1) : (i += 1) {
                            _ = bun.handleOom(out.rows.append(DirectRow{ .name_hash = owner_deps[@as(usize, @intCast(i))].name_hash, .behavior = owner_deps[@as(usize, @intCast(i))].behavior, .resolved = owner_res[@as(usize, @intCast(i))] }));
                        }
                    }
                    _ = bun.handleOom(out.owners.append(DirectOwner{ .owner = @intCast(owner), .start = start, .len = @intCast((out.rows.items.len - start)) }));
                }
            }
            return out;
    }

pub fn redirectDependents(self: DirectDependencies, lockfile: *Lockfile, loaded_package_count: usize) void {
            if (((self.owners.items.len == 0) or (loaded_package_count == 0))) {
                return;
            }
            var pairs = self.movedPairs(lockfile.allocator, lockfile);
            _ = &pairs;
            defer {
            _ = pairs.deinit();
            }
            _ = redirect(lockfile, pairs.items);
    }

pub fn movedPairs(self: DirectDependencies, allocator: Allocator, lockfile: *const Lockfile) std.array_list.Managed(PackageIdPair) {
            const packages_len = lockfile.packages.len;
            const pkg_res: []const Resolution = lockfile.packages.items(.resolution);
            const name_hashes: []const PackageNameHash = lockfile.packages.items(.name_hash);
            const dep_slices: []const Lockfile.DependencySlice = lockfile.packages.items(.dependencies);
            const res_slices = lockfile.packages.items(.resolutions);
            const deps = lockfile.buffers.dependencies.items;
            const resolutions = lockfile.buffers.resolutions.items;
            var pairs = std.array_list.Managed(PackageIdPair).init(allocator);
            _ = &pairs;
            for (self.owners.items) |o| {
                _ = &o;
                const owner: usize = o.owner;
                if ((owner >= packages_len)) {
                    continue;
                }
                const rows = self.rows.items[o.start..(o.start + o.len)];
                var claimed: ?DynamicBitSet = null;
                _ = &claimed;
                defer {
                if (claimed) |*c| {
                    _ = &c;
                    _ = (c.*).deinit();
                }
                }
                const owner_deps = dep_slices[@as(usize, @intCast(owner))].get(deps);
                const owner_res = res_slices[@as(usize, @intCast(owner))].get(resolutions);
                {
                    var i: i32 = 0;
                    _ = &i;
                    const __end_3 = owner_deps.len;
                    while (i < __end_3) : (i += 1) {
                        const dep = owner_deps[@as(usize, @intCast(i))];
                        const new_id = owner_res[@as(usize, @intCast(i))];
                        var index: usize = 0;
                        _ = &index;
                        var found_idx = false;
                        _ = &found_idx;
                        if (((((claimed == null) and (i < rows.len)) and (rows[@as(usize, @intCast(i))].name_hash == dep.name_hash)) and (@as(u8, @bitCast(rows[@as(usize, @intCast(i))].behavior)) == @as(u8, @bitCast(dep.behavior))))) {
                            index = @as(usize, @intCast(i));
                            found_idx = true;
                        } else {
                            if ((claimed == null)) {
                                var taken = bun.handleOom(DynamicBitSet.initEmpty(allocator, rows.len));
                                _ = &taken;
                                _ = taken.setRangeValue(.{ .start = 0, .end = @min(@as(usize, @intCast(i)), rows.len) }, true);
                                claimed = taken;
                            }
                            if (claimed) |*taken| {
                                _ = &taken;
                                if (((((@as(usize, @intCast(i)) < (taken.*).capacity()) and (!(taken.*).isSet(@as(usize, @intCast(i))))) and (rows[@as(usize, @intCast(i))].name_hash == dep.name_hash)) and (@as(u8, @bitCast(rows[@as(usize, @intCast(i))].behavior)) == @as(u8, @bitCast(dep.behavior))))) {
                                    index = @as(usize, @intCast(i));
                                    found_idx = true;
                                } else {
                                    {
                                        var k: i32 = 0;
                                        _ = &k;
                                        const __end_4 = rows.len;
                                        while (k < __end_4) : (k += 1) {
                                            if ((((!(taken.*).isSet(@as(usize, @intCast(k)))) and (rows[@as(usize, @intCast(k))].name_hash == dep.name_hash)) and (@as(u8, @bitCast(rows[@as(usize, @intCast(k))].behavior)) == @as(u8, @bitCast(dep.behavior))))) {
                                                index = @as(usize, @intCast(k));
                                                found_idx = true;
                                                break;
                                            }
                                        }
                                    }
                                }
                                if (found_idx) {
                                    _ = (taken.*).set(index);
                                }
                            }
                        }
                        if ((!found_idx)) {
                            continue;
                        }
                        const old_id = rows[@as(usize, @intCast(index))].resolved;
                        if ((((old_id == new_id) or (old_id >= packages_len)) or (new_id >= packages_len))) {
                            continue;
                        }
                        if ((pkg_res[@as(usize, @intCast(new_id))].tag != .npm)) {
                            continue;
                        }
                        if ((name_hashes[@as(usize, @intCast(old_id))] != name_hashes[@as(usize, @intCast(new_id))])) {
                            continue;
                        }
                        _ = bun.handleOom(pairs.append(PackageIdPair{ .old = old_id, .new = new_id }));
                    }
                }
            }
            return pairs;
    }
};

pub const TransitiveUpdate = struct {
    pins: std.array_list.Managed(Pin),
    report: ?Report,

pub fn initEmpty(allocator: Allocator) TransitiveUpdate {
            return TransitiveUpdate{ .pins = std.array_list.Managed(Pin).init(allocator), .report = null };
    }

pub fn deinit(self: *TransitiveUpdate) void {
            _ = self.pins.deinit();
            if (self.report) |*r| {
                _ = &r;
                _ = (r.*).deinit();
            }
    }

pub fn plan(manager: *PackageManager, direct: *const DirectDependencies) !TransitiveUpdate {
            const lockfile = manager.lockfile;
            var scope = UpdateScope.of(manager);
            _ = &scope;
            defer {
            _ = scope.deinit();
            }
            var edges = bun.handleOom(DynamicBitSet.initEmpty(lockfile.allocator, lockfile.buffers.dependencies.items.len));
            _ = &edges;
            defer {
            _ = edges.deinit();
            }
            const whole = scope.isWholeWorkspace();
            const owners_opt: ?*const DynamicBitSet = (if ((!whole)) scope.reachable(lockfile) else null);
            {
                var owner: i32 = 0;
                _ = &owner;
                const __end_5 = lockfile.packages.len;
                while (owner < __end_5) : (owner += 1) {
                    var in_scope = true;
                    _ = &in_scope;
                    if ((owners_opt != null)) {
                        const r = owners_opt.?;
                        in_scope = ((owner < r.capacity()) and r.isSet(@as(usize, @intCast(owner))));
                    }
                    if (in_scope) {
                        _ = setRowsOf((&edges), lockfile, @as(usize, @intCast(owner)));
                    }
                }
            }
            var plan_res = try planEdges(manager, (&edges), direct);
            _ = &plan_res;
            _ = try registerMoved(manager, plan_res.report.moved.items);
            const printed_here = (manager.options.dry_run or manager.options.lockfile_only);
            if ((!printed_here)) {
                _ = plan_res.report.deinit();
            }
            return TransitiveUpdate{ .pins = plan_res.pins, .report = (if (printed_here) plan_res.report else null) };
    }

pub fn enqueue(self: TransitiveUpdate, manager: *PackageManager) !void {
            return self.enqueueInner(manager, null);
    }

pub fn enqueueTracked(self: TransitiveUpdate, manager: *PackageManager) !DynamicBitSet {
            var pinned = bun.handleOom(DynamicBitSet.initEmpty(manager.allocator, manager.lockfile.buffers.resolutions.items.len));
            _ = &pinned;
            _ = try self.enqueueInner(manager, (&pinned));
            return pinned;
    }

pub fn enqueueInner(self: TransitiveUpdate, manager: *PackageManager, pinned: ?*DynamicBitSet) !void {
            if ((self.pins.items.len == 0)) {
                return;
            }
            _ = manager.getCacheDirectory();
            _ = manager.getTemporaryDirectory();
            for (self.pins.items) |pin| {
                _ = &pin;
                if ((manager.lockfile.buffers.resolutions.items[@as(usize, @intCast(pin.dep_id))] != pin.from_id)) {
                    continue;
                }
                if (pin.to) |to| {
                    _ = &to;
                    _ = try audit_fix.enqueuePinned(manager, pin.dep_id, to);
                } else {
                    _ = try reresolve(manager, pin.dep_id);
                }
                if (pinned) |p| {
                    _ = &p;
                    _ = p.set(pin.dep_id);
                }
                manager.summary.update = (manager.summary.update + 1);
            }
    }

pub fn printPlan(self: TransitiveUpdate, manager: *PackageManager, direct: *const DirectDependencies, named: []const DepMove) void {
            const options = manager.options;
            if ((((manager.subcommand != .update) or (!(options.dry_run or options.lockfile_only))) or (!options.do.summary))) {
                return;
            }
            const dry_run = options.dry_run;
            const alloc = manager.allocator;
            var rows = std.array_list.Managed(Row).init(alloc);
            _ = &rows;
            defer {
            _ = rows.deinit();
            }
            if (self.report) |rep| {
                _ = &rep;
                for (rep.rows.items) |r| {
                    _ = &r;
                    _ = bun.handleOom(rows.append(r));
                }
            }
            var pairs = direct.movedPairs(alloc, manager.lockfile);
            _ = &pairs;
            defer {
            _ = pairs.deinit();
            }
            var np = namedPairs(alloc, manager.lockfile, named);
            _ = &np;
            defer {
            _ = np.deinit();
            }
            for (np.items) |p| {
                _ = &p;
                _ = bun.handleOom(pairs.append(p));
            }
            var between = rowsBetween(manager, pairs.items);
            _ = &between;
            defer {
            _ = between.deinit();
            }
            for (between.items) |r| {
                _ = &r;
                _ = bun.handleOom(rows.append(r));
            }
            _ = sortDedupRows((&rows));
            var kept = keptPatchedRows(manager);
            _ = &kept;
            defer {
            _ = kept.deinit();
            }
            if ((((!dry_run) and (rows.items.len == 0)) and (kept.items.len == 0))) {
                return;
            }
            _ = Output.prettyln("", .{});
            _ = printRows(rows.items);
            _ = printKeptRows(kept.items);
            if (dry_run) {
                if (((rows.items.len > 0) or (kept.items.len > 0))) {
                    _ = Output.prettyln("", .{});
                }
                if ((rows.items.len == 0)) {
                    const n = manager.lockfile.packages.len;
                    const s: []const u8 = (if ((n == 1)) "" else "s");
                    _ = Output.pretty("Checked <green>{d} package{s}<r>, nothing to update ", .{ n, s });
                } else {
                    const n = rows.items.len;
                    const s: []const u8 = (if ((n == 1)) "" else "s");
                    _ = Output.pretty("<green>{d}<r> package{s} would be updated ", .{ n, s });
                }
                _ = Output.printStartEndStdout(bun.cli.start_time, std.time.nanoTimestamp());
                _ = Output.prettyln("", .{});
            }
            _ = Output.flush();
    }

pub fn redirectDependents(self: TransitiveUpdate, lockfile: *Lockfile) void {
            var moved = std.array_list.Managed(DepMove).init(lockfile.allocator);
            _ = &moved;
            defer {
            _ = moved.deinit();
            }
            for (self.pins.items) |pin| {
                _ = &pin;
                _ = bun.handleOom(moved.append(DepMove{ .dep_id = pin.dep_id, .from_id = pin.from_id }));
            }
            _ = redirectMovedEdges(lockfile, moved.items);
    }
};

pub const PlanResult = struct {
    pins: std.array_list.Managed(Pin),
    report: Report,
};

const string = []const u8;
const Allocator = std.mem.Allocator;
const DynamicBitSet = bun.bit_set.DynamicBitSet;
const Output = bun.Output;
const Semver = bun.Semver;
const String = Semver.String;
const strings = bun.strings;
const DependencyID = install.DependencyID;
const PackageID = install.PackageID;
const PackageNameHash = install.PackageNameHash;
