pub fn laterInCache(manager: *PackageManager, pkg_id: PackageID) []const u8 {
        const lockfile = manager.lockfile;
        const buf = lockfile.buffers.string_bytes.items;
        const str_slice = bun.Semver.String.slice;
        const name = str_slice((&lockfile.packages.items(.name)[@as(usize, @intCast(pkg_id))]), buf);
