pub fn movedTargetsAfterClean(allocator: Allocator, before_clean: *const Lockfile, cleaned: *const Lockfile, moved: []const DepMove) std.array_list.Managed(PackageID) {
        var targets = std.array_list.Managed(PackageID).init(allocator);
        _ = &targets;
        if ((moved.len == 0)) {
